// @sourcefile .\Src\D2WinTextBox.cpp
BOOL __fastcall D2WINTEXTBOX_WordWrapAndSetText(::D2WinTextBox * pTextBox, uint16_t * wszText, int32_t nLineStyle, int32_t nAlignment) {
    uint16_t* pSecondLine;
    int nAvailWidth;
    size_t nPrevCharCount;
    size_t nWrapCharCount;
    uint16_t wszIndentBuf[6];
    uint16_t* pWorkBuf;
    int32_t nTotalLen;
    uint16_t* pLastSpace;
    int nMaxPixelWidth;
    uint16_t* pCharCursor;
    int32_t nLine;
    uint16_t* pszCurScan = wszText;
    ::D2WinTextBox* pTextBoxSaved = pTextBox;
    if (!pTextBox) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x482);
      exit(-1);
    } else {
      uint16_t* pFirstLine;
      if (pTextBox->sControl.neD2FormType != FORM_TextBox) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x483);
        exit(-1);
      }

      nAvailWidth = pTextBox->sControl.dwSizeX + pTextBox->sListState.nTextOffsetX * -2;
      nMaxPixelWidth = nAvailWidth;
      if (nAlignment == 2) {
        Fog::File::CONTAINER_InitializeBuffer(wszIndentBuf, 2, 6, D2Lang::Unicode::UNISYS::STRING_ZeroOneWCHAR);
        memcpy(wszIndentBuf, L"     ", 0xc);
        nLine = D2WinFont::DRAW_text0(wszIndentBuf);
        nMaxPixelWidth = nAvailWidth - nLine;
      }

      pFirstLine = (uint16_t*)Storm::Source::SMem::SMemAlloc(0x800, ".\\Src\\D2WinTextBox.cpp", 0x497, 0);
      pWorkBuf = pFirstLine;
      D2Lang::Unicode::UNISYS::STRING_CopyWideString(pFirstLine, wszText);
      nTotalLen = D2Lang::Unicode::UNISYS::STRING_GetWideStringLength(pFirstLine);
      pLastSpace = 0;
      pCharCursor = pFirstLine;
      nWrapCharCount = 0;
      nPrevCharCount = 0;
      if (nTotalLen > 0) {
        do {
          if (*pCharCursor == L' ') {
            pLastSpace = pCharCursor;
          }

          nWrapCharCount = nPrevCharCount + 1;
          nLine = D2WinFont::D2WINFONT_GetStringPixelWidth(pszCurScan, nWrapCharCount);
          if (nLine >= nMaxPixelWidth) {
            nWrapCharCount = nPrevCharCount;
            if (pLastSpace) {
              nWrapCharCount = (intptr_t)pLastSpace - (intptr_t)pFirstLine >> 1;
              pCharCursor = pLastSpace;
            }

            break;
          }

          pCharCursor++;
          nPrevCharCount = nWrapCharCount;
        } while ((int)nWrapCharCount < nTotalLen);
      }

      pFirstLine = (uint16_t*)Storm::Source::SMem::SMemAlloc(0x800, ".\\Src\\D2WinTextBox.cpp", 0x4b7, 0);
      pSecondLine = (uint16_t*)Storm::Source::SMem::SMemAlloc(0x800, ".\\Src\\D2WinTextBox.cpp", 0x4b8, 0);
      D2Lang::Unicode::UNISYS::WSTRING_PutWideCharIntoBuffer(pFirstLine, pWorkBuf, nWrapCharCount);
      pszCurScan = (uint16_t*)(nTotalLen - nWrapCharCount);
      pFirstLine[nWrapCharCount] = L'\0';
      D2Lang::Unicode::UNISYS::WSTRING_PutWideCharIntoBuffer(pSecondLine, pCharCursor, (size_t)pszCurScan);
      pSecondLine[(int)pszCurScan] = L'\0';
      Storm::Source::SMem::SMemFree(pWorkBuf, ".\\Src\\D2WinTextBox.cpp", 0x4bf, 0);
      D2WinTextBox::SetText(pTextBoxSaved, pFirstLine, nLineStyle, true, nAlignment);
      if (nAlignment == 1) {
        nAlignment = 2;
      }

      D2WinTextBox::SetText(pTextBoxSaved, pSecondLine, nLineStyle, false, nAlignment);
      Storm::Source::SMem::SMemFree(pFirstLine, ".\\Src\\D2WinTextBox.cpp", 0x4c4, 0);
      Storm::Source::SMem::SMemFree(pSecondLine, ".\\Src\\D2WinTextBox.cpp", 0x4c5, 0);
      return 1;
    }
}

